window.LEX_LIBRARY.questions.push(...[{"id": "lawtext-A0030055-73-3", "subject": "行政法", "topic": "行政程序・§73", "kind": "法條", "question": "【法條原文辨識】依《行政程序法》第73條，下列節錄的【空格】應填入何者？\n\n「應受送達人或其同居人、受雇人、接收郵件人員無【空格】拒絕收領文書時，得將文書留置於應送達處所，以為送達。」", "options": ["犯罪嫌疑", "違法事由", "重大過失", "正當理由"], "answer": 3, "explanations": ["此處不是「犯罪嫌疑」。行政程序法第73條在本題位置規定的是「正當理由」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「違法事由」。行政程序法第73條在本題位置規定的是「正當理由」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「重大過失」。行政程序法第73條在本題位置規定的是「正當理由」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。行政程序法第73條此處原文是「正當理由」。\n原句：應受送達人或其同居人、受雇人、接收郵件人員無正當理由拒絕收領文書時，得將文書留置於應送達處所，以為送達。"], "hint": "先判斷空格要填的是行政程序，再核對條件與例外。", "sources": [{"title": "行政程序法第73條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=A0030055&flno=73", "text": "於應送達處所不獲會晤應受送達人時，得將文書付與有辨別事理能力之同居人、受雇人或應送達處所之接收郵件人員。\n前項規定於前項人員與應受送達人在該行政程序上利害關係相反者，不適用之。\n應受送達人或其同居人、受雇人、接收郵件人員無正當理由拒絕收領文書時，得將文書留置於應送達處所，以為送達。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-A0030055-151-2", "subject": "行政法", "topic": "行政程序・§151", "kind": "法條", "question": "【法條原文辨識】依《行政程序法》第151條，下列節錄的【空格】應填入何者？\n\n「法規命令之修正、【空格】、停止或恢復適用，準用訂定程序之規定。」", "options": ["撤銷", "補正", "更正", "廢止"], "answer": 3, "explanations": ["此處不是「撤銷」。行政程序法第151條在本題位置規定的是「廢止」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「補正」。行政程序法第151條在本題位置規定的是「廢止」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「更正」。行政程序法第151條在本題位置規定的是「廢止」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。行政程序法第151條此處原文是「廢止」。\n原句：法規命令之修正、廢止、停止或恢復適用，準用訂定程序之規定。"], "hint": "先判斷空格要填的是行政程序，再核對條件與例外。", "sources": [{"title": "行政程序法第151條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=A0030055&flno=151", "text": "行政機關訂定法規命令，除關於軍事、外交或其他重大事項而涉及國家機密或安全者外，應依本法所定程序為之。但法律另有規定者，從其規定。\n法規命令之修正、廢止、停止或恢復適用，準用訂定程序之規定。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-A0030055-21-6", "subject": "行政法", "topic": "憲政原則・§21", "kind": "法條", "question": "【法條原文辨識】依《行政程序法》第21條，下列節錄的【空格】應填入何者？\n\n「五、其他依【空格】規定得為權利義務之主體者。」", "options": ["命令", "法律", "法理", "習慣"], "answer": 1, "explanations": ["此處不是「命令」。行政程序法第21條在本題位置規定的是「法律」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。行政程序法第21條此處原文是「法律」。\n原句：五、其他依法律規定得為權利義務之主體者。", "此處不是「法理」。行政程序法第21條在本題位置規定的是「法律」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「習慣」。行政程序法第21條在本題位置規定的是「法律」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是憲政原則，再核對條件與例外。", "sources": [{"title": "行政程序法第21條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=A0030055&flno=21", "text": "有行政程序之當事人能力者如下︰\n一、自然人。\n二、法人。\n三、非法人之團體設有代表人或管理人者。\n四、行政機關。\n五、其他依法律規定得為權利義務之主體者。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-A0030055-72-1", "subject": "行政法", "topic": "憲政原則・§72", "kind": "法條", "question": "【法條原文辨識】依《行政程序法》第72條，下列節錄的【空格】應填入何者？\n\n「送達，於應受送達人之住居所、事務所或營業所為之。但在【空格】機關辦公處所或他處會晤應受送達人時，得於會晤處所為之。」", "options": ["司法", "行政", "立法", "監察"], "answer": 1, "explanations": ["此處不是「司法」。行政程序法第72條在本題位置規定的是「行政」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。行政程序法第72條此處原文是「行政」。\n原句：送達，於應受送達人之住居所、事務所或營業所為之。但在行政機關辦公處所或他處會晤應受送達人時，得於會晤處所為之。", "此處不是「立法」。行政程序法第72條在本題位置規定的是「行政」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「監察」。行政程序法第72條在本題位置規定的是「行政」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是憲政原則，再核對條件與例外。", "sources": [{"title": "行政程序法第72條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=A0030055&flno=72", "text": "送達，於應受送達人之住居所、事務所或營業所為之。但在行政機關辦公處所或他處會晤應受送達人時，得於會晤處所為之。\n對於機關、法人、非法人之團體之代表人或管理人為送達者，應向其機關所在地、事務所或營業所行之。但必要時亦得於會晤之處所或其住居所行之。\n應受送達人有就業處所者，亦得向該處所為送達。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-A0030055-6-1", "subject": "行政法", "topic": "行政程序・§6", "kind": "法條", "question": "【法條原文辨識】依《行政程序法》第6條，下列節錄的【空格】應填入何者？\n\n「行政行為，非有【空格】，不得為差別待遇。」", "options": ["重大過失", "正當理由", "犯罪嫌疑", "違法事由"], "answer": 1, "explanations": ["此處不是「重大過失」。行政程序法第6條在本題位置規定的是「正當理由」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。行政程序法第6條此處原文是「正當理由」。\n原句：行政行為，非有正當理由，不得為差別待遇。", "此處不是「犯罪嫌疑」。行政程序法第6條在本題位置規定的是「正當理由」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「違法事由」。行政程序法第6條在本題位置規定的是「正當理由」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是行政程序，再核對條件與例外。", "sources": [{"title": "行政程序法第6條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=A0030055&flno=6", "text": "行政行為，非有正當理由，不得為差別待遇。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1146-2", "subject": "繼承法", "topic": "期間・數額・比例・§1146", "kind": "法條", "question": "【法條原文辨識】依《民法》第1146條，下列節錄的【空格】應填入何者？\n\n「前項回復請求權，自知悉被侵害之時起，二年間不行使而消滅；自繼承開始時起逾【空格】者亦同。」", "options": ["二年", "一年", "三年", "十年"], "answer": 3, "explanations": ["此處不是「二年」。民法第1146條在本題位置規定的是「十年」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「一年」。民法第1146條在本題位置規定的是「十年」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「三年」。民法第1146條在本題位置規定的是「十年」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1146條此處原文是「十年」。\n原句：前項回復請求權，自知悉被侵害之時起，二年間不行使而消滅；自繼承開始時起逾十年者亦同。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第1146條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1146", "text": "繼承權被侵害者，被害人或其法定代理人得請求回復之。\n前項回復請求權，自知悉被侵害之時起，二年間不行使而消滅；自繼承開始時起逾十年者亦同。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1152-1", "subject": "繼承法", "topic": "期間・數額・比例・§1152", "kind": "法條", "question": "【法條原文辨識】依《民法》第1152條，下列節錄的【空格】應填入何者？\n\n「前條公同共有之遺產，得由繼承人中互推【空格】管理之。」", "options": ["三人", "一人", "二人", "五人"], "answer": 1, "explanations": ["此處不是「三人」。民法第1152條在本題位置規定的是「一人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1152條此處原文是「一人」。\n原句：前條公同共有之遺產，得由繼承人中互推一人管理之。", "此處不是「二人」。民法第1152條在本題位置規定的是「一人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「五人」。民法第1152條在本題位置規定的是「一人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第1152條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1152", "text": "前條公同共有之遺產，得由繼承人中互推一人管理之。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1159-3", "subject": "繼承法", "topic": "行政程序・§1159", "kind": "法條", "question": "【法條原文辨識】依《民法》第1159條，下列節錄的【空格】應填入何者？\n\n「前項未屆清償期之債權，於繼承開始時，視為已到期。其無利息者，其債權額應扣除自第一千一百五十七條所定之一定【空格】屆滿時起至到期時止之法定利息。」", "options": ["負擔", "保留廢止權", "條件", "期限"], "answer": 3, "explanations": ["此處不是「負擔」。民法第1159條在本題位置規定的是「期限」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「保留廢止權」。民法第1159條在本題位置規定的是「期限」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「條件」。民法第1159條在本題位置規定的是「期限」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1159條此處原文是「期限」。\n原句：前項未屆清償期之債權，於繼承開始時，視為已到期。其無利息者，其債權額應扣除自第一千一百五十七條所定之一定期限屆滿時起至到期時止之法定利息。"], "hint": "先判斷空格要填的是行政程序，再核對條件與例外。", "sources": [{"title": "民法第1159條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1159", "text": "在第一千一百五十七條所定之一定期限屆滿後，繼承人對於在該一定期限內報明之債權及繼承人所已知之債權，均應按其數額，比例計算，以遺產分別償還。但不得害及有優先權人之利益。\n繼承人對於繼承開始時未屆清償期之債權，亦應依第一項規定予以清償。\n前項未屆清償期之債權，於繼承開始時，視為已到期。其無利息者，其債權額應扣除自第一千一百五十七條所定之一定期限屆滿時起至到期時止之法定利息。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1176-1-1", "subject": "繼承法", "topic": "權利主體・§1176-1", "kind": "法條", "question": "【法條原文辨識】依《民法》第1176-1條，下列節錄的【空格】應填入何者？\n\n「拋棄繼承權者，就其所管理之遺產，於其他【空格】或遺產管理人開始管理前，應與處理自己事務為同一之注意，繼續管理之。」", "options": ["遺囑執行人", "受遺贈人", "繼承人", "被繼承人"], "answer": 2, "explanations": ["此處不是「遺囑執行人」。民法第1176-1條在本題位置規定的是「繼承人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「受遺贈人」。民法第1176-1條在本題位置規定的是「繼承人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1176-1條此處原文是「繼承人」。\n原句：拋棄繼承權者，就其所管理之遺產，於其他繼承人或遺產管理人開始管理前，應與處理自己事務為同一之注意，繼續管理之。", "此處不是「被繼承人」。民法第1176-1條在本題位置規定的是「繼承人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是權利主體，再核對條件與例外。", "sources": [{"title": "民法第1176-1條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1176-1", "text": "拋棄繼承權者，就其所管理之遺產，於其他繼承人或遺產管理人開始管理前，應與處理自己事務為同一之注意，繼續管理之。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1205-1", "subject": "繼承法", "topic": "權利主體・§1205", "kind": "法條", "question": "【法條原文辨識】依《民法》第1205條，下列節錄的【空格】應填入何者？\n\n「遺贈附有義務者，【空格】以其所受利益為限，負履行之責。」", "options": ["繼承人", "遺囑執行人", "受遺贈人", "被繼承人"], "answer": 2, "explanations": ["此處不是「繼承人」。民法第1205條在本題位置規定的是「受遺贈人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「遺囑執行人」。民法第1205條在本題位置規定的是「受遺贈人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1205條此處原文是「受遺贈人」。\n原句：遺贈附有義務者，受遺贈人以其所受利益為限，負履行之責。", "此處不是「被繼承人」。民法第1205條在本題位置規定的是「受遺贈人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是權利主體，再核對條件與例外。", "sources": [{"title": "民法第1205條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1205", "text": "遺贈附有義務者，受遺贈人以其所受利益為限，負履行之責。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1203-1", "subject": "繼承法", "topic": "物權種類・§1203", "kind": "法條", "question": "【法條原文辨識】依《民法》第1203條，下列節錄的【空格】應填入何者？\n\n「遺囑人因遺贈物滅失、毀損、變造、或喪失物之【空格】，而對於他人取得權利時，推定以其權利為遺贈；因遺贈物與他物附合或混合而對於所附合或混合之物取得權利時亦同。」", "options": ["使用", "占有", "共有", "所有"], "answer": 1, "explanations": ["此處不是「使用」。民法第1203條在本題位置規定的是「占有」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1203條此處原文是「占有」。\n原句：遺囑人因遺贈物滅失、毀損、變造、或喪失物之占有，而對於他人取得權利時，推定以其權利為遺贈；因遺贈物與他物附合或混合而對於所附合或混合之物取得權利時亦同。", "此處不是「共有」。民法第1203條在本題位置規定的是「占有」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「所有」。民法第1203條在本題位置規定的是「占有」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是物權種類，再核對條件與例外。", "sources": [{"title": "民法第1203條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1203", "text": "遺囑人因遺贈物滅失、毀損、變造、或喪失物之占有，而對於他人取得權利時，推定以其權利為遺贈；因遺贈物與他物附合或混合而對於所附合或混合之物取得權利時亦同。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1187-1", "subject": "繼承法", "topic": "憲政原則・§1187", "kind": "法條", "question": "【法條原文辨識】依《民法》第1187條，下列節錄的【空格】應填入何者？\n\n「遺囑人於不違反關於特留分規定之範圍內，得以遺囑【空格】處分遺產。」", "options": ["資格", "自由", "責任", "義務"], "answer": 1, "explanations": ["此處不是「資格」。民法第1187條在本題位置規定的是「自由」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1187條此處原文是「自由」。\n原句：遺囑人於不違反關於特留分規定之範圍內，得以遺囑自由處分遺產。", "此處不是「責任」。民法第1187條在本題位置規定的是「自由」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「義務」。民法第1187條在本題位置規定的是「自由」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是憲政原則，再核對條件與例外。", "sources": [{"title": "民法第1187條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1187", "text": "遺囑人於不違反關於特留分規定之範圍內，得以遺囑自由處分遺產。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1141-1", "subject": "繼承法", "topic": "憲政原則・§1141", "kind": "法條", "question": "【法條原文辨識】依《民法》第1141條，下列節錄的【空格】應填入何者？\n\n「同一順序之繼承人有數人時，按人數平均繼承。但【空格】另有規定者，不在此限。」", "options": ["法律", "法理", "命令", "習慣"], "answer": 0, "explanations": ["正確。民法第1141條此處原文是「法律」。\n原句：同一順序之繼承人有數人時，按人數平均繼承。但法律另有規定者，不在此限。", "此處不是「法理」。民法第1141條在本題位置規定的是「法律」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「命令」。民法第1141條在本題位置規定的是「法律」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「習慣」。民法第1141條在本題位置規定的是「法律」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是憲政原則，再核對條件與例外。", "sources": [{"title": "民法第1141條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1141", "text": "同一順序之繼承人有數人時，按人數平均繼承。但法律另有規定者，不在此限。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1166-2", "subject": "繼承法", "topic": "權利主體・§1166", "kind": "法條", "question": "【法條原文辨識】依《民法》第1166條，下列節錄的【空格】應填入何者？\n\n「胎兒關於遺產之分割，以其母為【空格】。」", "options": ["監護人", "輔助人", "法定代理人", "代理人"], "answer": 3, "explanations": ["此處不是「監護人」。民法第1166條在本題位置規定的是「代理人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「輔助人」。民法第1166條在本題位置規定的是「代理人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「法定代理人」。民法第1166條在本題位置規定的是「代理人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1166條此處原文是「代理人」。\n原句：胎兒關於遺產之分割，以其母為代理人。"], "hint": "先判斷空格要填的是權利主體，再核對條件與例外。", "sources": [{"title": "民法第1166條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1166", "text": "胎兒為繼承人時，非保留其應繼分，他繼承人不得分割遺產。\n胎兒關於遺產之分割，以其母為代理人。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1222-1", "subject": "繼承法", "topic": "債的效力・§1222", "kind": "法條", "question": "【法條原文辨識】依《民法》第1222條，下列節錄的【空格】應填入何者？\n\n「遺囑人故意破毀或塗銷遺囑，或在遺囑上記明廢棄之意思者，其遺囑視為【空格】。」", "options": ["撤回", "通知", "拒絕", "承認"], "answer": 0, "explanations": ["正確。民法第1222條此處原文是「撤回」。\n原句：遺囑人故意破毀或塗銷遺囑，或在遺囑上記明廢棄之意思者，其遺囑視為撤回。", "此處不是「通知」。民法第1222條在本題位置規定的是「撤回」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「拒絕」。民法第1222條在本題位置規定的是「撤回」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「承認」。民法第1222條在本題位置規定的是「撤回」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是債的效力，再核對條件與例外。", "sources": [{"title": "民法第1222條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1222", "text": "遺囑人故意破毀或塗銷遺囑，或在遺囑上記明廢棄之意思者，其遺囑視為撤回。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1220-1", "subject": "繼承法", "topic": "債的效力・§1220", "kind": "法條", "question": "【法條原文辨識】依《民法》第1220條，下列節錄的【空格】應填入何者？\n\n「前後遺囑有相牴觸者，其牴觸之部分，前遺囑視為【空格】。」", "options": ["承認", "通知", "撤回", "拒絕"], "answer": 2, "explanations": ["此處不是「承認」。民法第1220條在本題位置規定的是「撤回」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「通知」。民法第1220條在本題位置規定的是「撤回」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1220條此處原文是「撤回」。\n原句：前後遺囑有相牴觸者，其牴觸之部分，前遺囑視為撤回。", "此處不是「拒絕」。民法第1220條在本題位置規定的是「撤回」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是債的效力，再核對條件與例外。", "sources": [{"title": "民法第1220條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1220", "text": "前後遺囑有相牴觸者，其牴觸之部分，前遺囑視為撤回。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1148-1-1", "subject": "繼承法", "topic": "期間・數額・比例・§1148-1", "kind": "法條", "question": "【法條原文辨識】依《民法》第1148-1條，下列節錄的【空格】應填入何者？\n\n「繼承人在繼承開始前【空格】內，從被繼承人受有財產之贈與者，該財產視為其所得遺產。」", "options": ["五年", "二年", "一年", "三年"], "answer": 1, "explanations": ["此處不是「五年」。民法第1148-1條在本題位置規定的是「二年」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1148-1條此處原文是「二年」。\n原句：繼承人在繼承開始前二年內，從被繼承人受有財產之贈與者，該財產視為其所得遺產。", "此處不是「一年」。民法第1148-1條在本題位置規定的是「二年」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「三年」。民法第1148-1條在本題位置規定的是「二年」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第1148-1條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1148-1", "text": "繼承人在繼承開始前二年內，從被繼承人受有財產之贈與者，該財產視為其所得遺產。\n前項財產如已移轉或滅失，其價額，依贈與時之價值計算。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1172-1", "subject": "繼承法", "topic": "權利主體・§1172", "kind": "法條", "question": "【法條原文辨識】依《民法》第1172條，下列節錄的【空格】應填入何者？\n\n「繼承人中如對於【空格】負有債務者，於遺產分割時，應按其債務數額，由該繼承人之應繼分內扣還。」", "options": ["被繼承人", "受遺贈人", "遺囑執行人", "繼承人"], "answer": 0, "explanations": ["正確。民法第1172條此處原文是「被繼承人」。\n原句：繼承人中如對於被繼承人負有債務者，於遺產分割時，應按其債務數額，由該繼承人之應繼分內扣還。", "此處不是「受遺贈人」。民法第1172條在本題位置規定的是「被繼承人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「遺囑執行人」。民法第1172條在本題位置規定的是「被繼承人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「繼承人」。民法第1172條在本題位置規定的是「被繼承人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是權利主體，再核對條件與例外。", "sources": [{"title": "民法第1172條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1172", "text": "繼承人中如對於被繼承人負有債務者，於遺產分割時，應按其債務數額，由該繼承人之應繼分內扣還。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1160-1", "subject": "繼承法", "topic": "法律要件・§1160", "kind": "法條", "question": "【法條原文辨識】依《民法》第1160條，下列節錄的【空格】應填入何者？\n\n「繼承人非依前條規定償還債務後，不得對受遺贈人【空格】遺贈。」", "options": ["公告", "登記", "交付", "公證"], "answer": 2, "explanations": ["此處不是「公告」。民法第1160條在本題位置規定的是「交付」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「登記」。民法第1160條在本題位置規定的是「交付」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1160條此處原文是「交付」。\n原句：繼承人非依前條規定償還債務後，不得對受遺贈人交付遺贈。", "此處不是「公證」。民法第1160條在本題位置規定的是「交付」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是法律要件，再核對條件與例外。", "sources": [{"title": "民法第1160條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1160", "text": "繼承人非依前條規定償還債務後，不得對受遺贈人交付遺贈。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1213-1", "subject": "繼承法", "topic": "法律要件・§1213", "kind": "法條", "question": "【法條原文辨識】依《民法》第1213條，下列節錄的【空格】應填入何者？\n\n「有封緘之遺囑，非在親屬會議當場或法院【空格】處，不得開視。」", "options": ["交付", "公告", "登記", "公證"], "answer": 3, "explanations": ["此處不是「交付」。民法第1213條在本題位置規定的是「公證」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「公告」。民法第1213條在本題位置規定的是「公證」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「登記」。民法第1213條在本題位置規定的是「公證」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1213條此處原文是「公證」。\n原句：有封緘之遺囑，非在親屬會議當場或法院公證處，不得開視。"], "hint": "先判斷空格要填的是法律要件，再核對條件與例外。", "sources": [{"title": "民法第1213條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1213", "text": "有封緘之遺囑，非在親屬會議當場或法院公證處，不得開視。\n前項遺囑開視時，應製作紀錄，記明遺囑之封緘有無毀損情形，或其他特別情事，並由在場之人同行簽名。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1145-3", "subject": "繼承法", "topic": "法律效果・§1145", "kind": "法條", "question": "【法條原文辨識】依《民法》第1145條，下列節錄的【空格】應填入何者？\n\n「二、以詐欺或脅迫使被繼承人為關於繼承之遺囑，或使其撤回或【空格】之者。」", "options": ["終止", "撤銷", "變更", "解除"], "answer": 2, "explanations": ["此處不是「終止」。民法第1145條在本題位置規定的是「變更」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「撤銷」。民法第1145條在本題位置規定的是「變更」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1145條此處原文是「變更」。\n原句：二、以詐欺或脅迫使被繼承人為關於繼承之遺囑，或使其撤回或變更之者。", "此處不是「解除」。民法第1145條在本題位置規定的是「變更」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是法律效果，再核對條件與例外。", "sources": [{"title": "民法第1145條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1145", "text": "有左列各款情事之一者，喪失其繼承權：\n一、故意致被繼承人或應繼承人於死或雖未致死因而受刑之宣告者。\n二、以詐欺或脅迫使被繼承人為關於繼承之遺囑，或使其撤回或變更之者。\n三、以詐欺或脅迫妨害被繼承人為關於繼承之遺囑，或妨害其撤回或變更之者。\n四、偽造、變造、隱匿或湮滅被繼承人關於繼承之遺囑者。\n五、對於被繼承人有重大之虐待或侮辱情事，經被繼承人表示其不得繼承者。\n前項第二款至第四款之規定，如經被繼承人宥恕者，其繼承權不喪失。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1198-5", "subject": "繼承法", "topic": "親屬與繼承・§1198", "kind": "法條", "question": "【法條原文辨識】依《民法》第1198條，下列節錄的【空格】應填入何者？\n\n「四、受遺贈人及其配偶或其【空格】。」", "options": ["直系血親", "旁系血親", "直系姻親", "旁系姻親"], "answer": 0, "explanations": ["正確。民法第1198條此處原文是「直系血親」。\n原句：四、受遺贈人及其配偶或其直系血親。", "此處不是「旁系血親」。民法第1198條在本題位置規定的是「直系血親」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「直系姻親」。民法第1198條在本題位置規定的是「直系血親」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「旁系姻親」。民法第1198條在本題位置規定的是「直系血親」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是親屬與繼承，再核對條件與例外。", "sources": [{"title": "民法第1198條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1198", "text": "下列之人，不得為遺囑見證人：\n一、未成年人。\n二、受監護或輔助宣告之人。\n三、繼承人及其配偶或其直系血親。\n四、受遺贈人及其配偶或其直系血親。\n五、為公證人或代行公證職務人之同居人助理人或受僱人。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1147-1", "subject": "繼承法", "topic": "權利主體・§1147", "kind": "法條", "question": "【法條原文辨識】依《民法》第1147條，下列節錄的【空格】應填入何者？\n\n「繼承，因【空格】死亡而開始。」", "options": ["被繼承人", "繼承人", "遺囑執行人", "受遺贈人"], "answer": 0, "explanations": ["正確。民法第1147條此處原文是「被繼承人」。\n原句：繼承，因被繼承人死亡而開始。", "此處不是「繼承人」。民法第1147條在本題位置規定的是「被繼承人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「遺囑執行人」。民法第1147條在本題位置規定的是「被繼承人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「受遺贈人」。民法第1147條在本題位置規定的是「被繼承人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是權利主體，再核對條件與例外。", "sources": [{"title": "民法第1147條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1147", "text": "繼承，因被繼承人死亡而開始。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1191-1", "subject": "繼承法", "topic": "期間・數額・比例・§1191", "kind": "法條", "question": "【法條原文辨識】依《民法》第1191條，下列節錄的【空格】應填入何者？\n\n「公證遺囑，應指定【空格】以上之見證人，在公證人前口述遺囑意旨，由公證人筆記、宣讀、講解，經遺囑人認可後，記明年、月、日，由公證人、見證人及遺囑人同行簽名，遺囑人不能簽名者，由公證人將其事由記明，使按指印代之。」", "options": ["二人", "五人", "一人", "三人"], "answer": 0, "explanations": ["正確。民法第1191條此處原文是「二人」。\n原句：公證遺囑，應指定二人以上之見證人，在公證人前口述遺囑意旨，由公證人筆記、宣讀、講解，經遺囑人認可後，記明年、月、日，由公證人、見證人及遺囑人同行簽名，遺囑人不能簽名者，由公證人將其事由記明，使按指印代之。", "此處不是「五人」。民法第1191條在本題位置規定的是「二人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「一人」。民法第1191條在本題位置規定的是「二人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「三人」。民法第1191條在本題位置規定的是「二人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第1191條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1191", "text": "公證遺囑，應指定二人以上之見證人，在公證人前口述遺囑意旨，由公證人筆記、宣讀、講解，經遺囑人認可後，記明年、月、日，由公證人、見證人及遺囑人同行簽名，遺囑人不能簽名者，由公證人將其事由記明，使按指印代之。\n前項所定公證人之職務，在無公證人之地，得由法院書記官行之，僑民在中華民國領事駐在地為遺囑時，得由領事行之。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1140-1", "subject": "繼承法", "topic": "親屬與繼承・§1140", "kind": "法條", "question": "【法條原文辨識】依《民法》第1140條，下列節錄的【空格】應填入何者？\n\n「第一千一百三十八條所定第一順序之繼承人，有於繼承開始前死亡或喪失繼承權者，由其【空格】代位繼承其應繼分。」", "options": ["祖父母", "兄弟姊妹", "父母", "直系血親卑親屬"], "answer": 3, "explanations": ["此處不是「祖父母」。民法第1140條在本題位置規定的是「直系血親卑親屬」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「兄弟姊妹」。民法第1140條在本題位置規定的是「直系血親卑親屬」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「父母」。民法第1140條在本題位置規定的是「直系血親卑親屬」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1140條此處原文是「直系血親卑親屬」。\n原句：第一千一百三十八條所定第一順序之繼承人，有於繼承開始前死亡或喪失繼承權者，由其直系血親卑親屬代位繼承其應繼分。"], "hint": "先判斷空格要填的是親屬與繼承，再核對條件與例外。", "sources": [{"title": "民法第1140條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1140", "text": "第一千一百三十八條所定第一順序之繼承人，有於繼承開始前死亡或喪失繼承權者，由其直系血親卑親屬代位繼承其應繼分。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1163-4", "subject": "繼承法", "topic": "物權種類・§1163", "kind": "法條", "question": "【法條原文辨識】依《民法》第1163條，下列節錄的【空格】應填入何者？\n\n「三、意圖詐害被繼承人之【空格】人之權利而為遺產之處分。」", "options": ["不動產", "債權", "有價證券", "動產"], "answer": 1, "explanations": ["此處不是「不動產」。民法第1163條在本題位置規定的是「債權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1163條此處原文是「債權」。\n原句：三、意圖詐害被繼承人之債權人之權利而為遺產之處分。", "此處不是「有價證券」。民法第1163條在本題位置規定的是「債權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「動產」。民法第1163條在本題位置規定的是「債權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是物權種類，再核對條件與例外。", "sources": [{"title": "民法第1163條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1163", "text": "繼承人中有下列各款情事之一者，不得主張第一千一百四十八條第二項所定之利益：\n一、隱匿遺產情節重大。\n二、在遺產清冊為虛偽之記載情節重大。\n三、意圖詐害被繼承人之債權人之權利而為遺產之處分。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1149-1", "subject": "繼承法", "topic": "親屬與繼承・§1149", "kind": "法條", "question": "【法條原文辨識】依《民法》第1149條，下列節錄的【空格】應填入何者？\n\n「被繼承人生前繼續扶養之人，應由【空格】依其所受扶養之程度及其他關係，酌給遺產。」", "options": ["法院", "戶政機關", "親屬會議", "檢察官"], "answer": 2, "explanations": ["此處不是「法院」。民法第1149條在本題位置規定的是「親屬會議」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「戶政機關」。民法第1149條在本題位置規定的是「親屬會議」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1149條此處原文是「親屬會議」。\n原句：被繼承人生前繼續扶養之人，應由親屬會議依其所受扶養之程度及其他關係，酌給遺產。", "此處不是「檢察官」。民法第1149條在本題位置規定的是「親屬會議」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是親屬與繼承，再核對條件與例外。", "sources": [{"title": "民法第1149條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1149", "text": "被繼承人生前繼續扶養之人，應由親屬會議依其所受扶養之程度及其他關係，酌給遺產。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1216-1", "subject": "繼承法", "topic": "權利主體・§1216", "kind": "法條", "question": "【法條原文辨識】依《民法》第1216條，下列節錄的【空格】應填入何者？\n\n「【空格】於遺囑執行人執行職務中，不得處分與遺囑有關之遺產，並不得妨礙其職務之執行。」", "options": ["受遺贈人", "遺囑執行人", "繼承人", "被繼承人"], "answer": 2, "explanations": ["此處不是「受遺贈人」。民法第1216條在本題位置規定的是「繼承人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「遺囑執行人」。民法第1216條在本題位置規定的是「繼承人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1216條此處原文是「繼承人」。\n原句：繼承人於遺囑執行人執行職務中，不得處分與遺囑有關之遺產，並不得妨礙其職務之執行。", "此處不是「被繼承人」。民法第1216條在本題位置規定的是「繼承人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是權利主體，再核對條件與例外。", "sources": [{"title": "民法第1216條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1216", "text": "繼承人於遺囑執行人執行職務中，不得處分與遺囑有關之遺產，並不得妨礙其職務之執行。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1164-1", "subject": "繼承法", "topic": "憲政原則・§1164", "kind": "法條", "question": "【法條原文辨識】依《民法》第1164條，下列節錄的【空格】應填入何者？\n\n「繼承人得隨時請求分割遺產。但【空格】另有規定或契約另有訂定者，不在此限。」", "options": ["命令", "習慣", "法理", "法律"], "answer": 3, "explanations": ["此處不是「命令」。民法第1164條在本題位置規定的是「法律」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「習慣」。民法第1164條在本題位置規定的是「法律」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「法理」。民法第1164條在本題位置規定的是「法律」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1164條此處原文是「法律」。\n原句：繼承人得隨時請求分割遺產。但法律另有規定或契約另有訂定者，不在此限。"], "hint": "先判斷空格要填的是憲政原則，再核對條件與例外。", "sources": [{"title": "民法第1164條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1164", "text": "繼承人得隨時請求分割遺產。但法律另有規定或契約另有訂定者，不在此限。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1196-1", "subject": "繼承法", "topic": "期間・數額・比例・§1196", "kind": "法條", "question": "【法條原文辨識】依《民法》第1196條，下列節錄的【空格】應填入何者？\n\n「口授遺囑，自遺囑人能依其他方式為遺囑之時起，經過【空格】而失其效力。」", "options": ["二個月", "一個月", "六個月", "三個月"], "answer": 3, "explanations": ["此處不是「二個月」。民法第1196條在本題位置規定的是「三個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「一個月」。民法第1196條在本題位置規定的是「三個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「六個月」。民法第1196條在本題位置規定的是「三個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1196條此處原文是「三個月」。\n原句：口授遺囑，自遺囑人能依其他方式為遺囑之時起，經過三個月而失其效力。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第1196條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1196", "text": "口授遺囑，自遺囑人能依其他方式為遺囑之時起，經過三個月而失其效力。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1165-2", "subject": "繼承法", "topic": "期間・數額・比例・§1165", "kind": "法條", "question": "【法條原文辨識】依《民法》第1165條，下列節錄的【空格】應填入何者？\n\n「遺囑禁止遺產之分割者，其禁止之效力以【空格】為限。」", "options": ["一年", "二年", "三年", "十年"], "answer": 3, "explanations": ["此處不是「一年」。民法第1165條在本題位置規定的是「十年」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「二年」。民法第1165條在本題位置規定的是「十年」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「三年」。民法第1165條在本題位置規定的是「十年」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1165條此處原文是「十年」。\n原句：遺囑禁止遺產之分割者，其禁止之效力以十年為限。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第1165條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1165", "text": "被繼承人之遺囑，定有分割遺產之方法，或託他人代定者，從其所定。\n遺囑禁止遺產之分割者，其禁止之效力以十年為限。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1176-7", "subject": "繼承法", "topic": "期間・數額・比例・§1176", "kind": "法條", "question": "【法條原文辨識】依《民法》第1176條，下列節錄的【空格】應填入何者？\n\n「因他人拋棄繼承而應為繼承之人，為拋棄繼承時，應於知悉其得繼承之日起【空格】內為之。」", "options": ["一個月", "三個月", "六個月", "二個月"], "answer": 1, "explanations": ["此處不是「一個月」。民法第1176條在本題位置規定的是「三個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1176條此處原文是「三個月」。\n原句：因他人拋棄繼承而應為繼承之人，為拋棄繼承時，應於知悉其得繼承之日起三個月內為之。", "此處不是「六個月」。民法第1176條在本題位置規定的是「三個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「二個月」。民法第1176條在本題位置規定的是「三個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第1176條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1176", "text": "第一千一百三十八條所定第一順序之繼承人中有拋棄繼承權者，其應繼分歸屬於其他同為繼承之人。\n第二順序至第四順序之繼承人中，有拋棄繼承權者，其應繼分歸屬於其他同一順序之繼承人。\n與配偶同為繼承之同一順序繼承人均拋棄繼承權，而無後順序之繼承人時，其應繼分歸屬於配偶。\n配偶拋棄繼承權者，其應繼分歸屬於與其同為繼承之人。\n第一順序之繼承人，其親等近者均拋棄繼承權時，由次親等之直系血親卑親屬繼承。\n先順序繼承人均拋棄其繼承權時，由次順序之繼承人繼承。其次順序繼承人有無不明或第四順序之繼承人均拋棄其繼承權者，準用關於無人承認繼承之規定。\n因他人拋棄繼承而應為繼承之人，為拋棄繼承時，應於知悉其得繼承之日起三個月內為之。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1183-1", "subject": "繼承法", "topic": "權利主體・§1183", "kind": "法條", "question": "【法條原文辨識】依《民法》第1183條，下列節錄的【空格】應填入何者？\n\n「遺產管理人得請求報酬，其數額由法院按其與【空格】之關係、管理事務之繁簡及其他情形，就遺產酌定之，必要時，得命聲請人先為墊付。」", "options": ["繼承人", "受遺贈人", "遺囑執行人", "被繼承人"], "answer": 3, "explanations": ["此處不是「繼承人」。民法第1183條在本題位置規定的是「被繼承人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「受遺贈人」。民法第1183條在本題位置規定的是「被繼承人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「遺囑執行人」。民法第1183條在本題位置規定的是「被繼承人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1183條此處原文是「被繼承人」。\n原句：遺產管理人得請求報酬，其數額由法院按其與被繼承人之關係、管理事務之繁簡及其他情形，就遺產酌定之，必要時，得命聲請人先為墊付。"], "hint": "先判斷空格要填的是權利主體，再核對條件與例外。", "sources": [{"title": "民法第1183條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1183", "text": "遺產管理人得請求報酬，其數額由法院按其與被繼承人之關係、管理事務之繁簡及其他情形，就遺產酌定之，必要時，得命聲請人先為墊付。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1170-1", "subject": "繼承法", "topic": "犯罪與責任・§1170", "kind": "法條", "question": "【法條原文辨識】依《民法》第1170條，下列節錄的【空格】應填入何者？\n\n「依前二條規定負擔保責任之繼承人中，有無支付能力不能償還其分擔額者，其不能償還之部分，由有請求權之繼承人與他繼承人，按其所得部分比例分擔之。但其不能償還，係由有請求權人之【空格】所致者，不得對於他繼承人請求分擔。」", "options": ["故意", "正當防衛", "過失", "緊急避難"], "answer": 2, "explanations": ["此處不是「故意」。民法第1170條在本題位置規定的是「過失」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「正當防衛」。民法第1170條在本題位置規定的是「過失」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1170條此處原文是「過失」。\n原句：依前二條規定負擔保責任之繼承人中，有無支付能力不能償還其分擔額者，其不能償還之部分，由有請求權之繼承人與他繼承人，按其所得部分比例分擔之。但其不能償還，係由有請求權人之過失所致者，不得對於他繼承人請求分擔。", "此處不是「緊急避難」。民法第1170條在本題位置規定的是「過失」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是犯罪與責任，再核對條件與例外。", "sources": [{"title": "民法第1170條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1170", "text": "依前二條規定負擔保責任之繼承人中，有無支付能力不能償還其分擔額者，其不能償還之部分，由有請求權之繼承人與他繼承人，按其所得部分比例分擔之。但其不能償還，係由有請求權人之過失所致者，不得對於他繼承人請求分擔。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1225-1", "subject": "繼承法", "topic": "權利主體・§1225", "kind": "法條", "question": "【法條原文辨識】依《民法》第1225條，下列節錄的【空格】應填入何者？\n\n「應得特留分之人，如因被繼承人所為之遺贈，致其應得之數不足者，得按其不足之數由遺贈財產扣減之。【空格】有數人時，應按其所得遺贈價額比例扣減。」", "options": ["遺囑執行人", "受遺贈人", "被繼承人", "繼承人"], "answer": 1, "explanations": ["此處不是「遺囑執行人」。民法第1225條在本題位置規定的是「受遺贈人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1225條此處原文是「受遺贈人」。\n原句：應得特留分之人，如因被繼承人所為之遺贈，致其應得之數不足者，得按其不足之數由遺贈財產扣減之。受遺贈人有數人時，應按其所得遺贈價額比例扣減。", "此處不是「被繼承人」。民法第1225條在本題位置規定的是「受遺贈人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「繼承人」。民法第1225條在本題位置規定的是「受遺贈人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是權利主體，再核對條件與例外。", "sources": [{"title": "民法第1225條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1225", "text": "應得特留分之人，如因被繼承人所為之遺贈，致其應得之數不足者，得按其不足之數由遺贈財產扣減之。受遺贈人有數人時，應按其所得遺贈價額比例扣減。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1161-2", "subject": "繼承法", "topic": "權利主體・§1161", "kind": "法條", "question": "【法條原文辨識】依《民法》第1161條，下列節錄的【空格】應填入何者？\n\n「前項受有損害之人，對於不當受領之債權人或【空格】，得請求返還其不當受領之數額。」", "options": ["受遺贈人", "被繼承人", "遺囑執行人", "繼承人"], "answer": 0, "explanations": ["正確。民法第1161條此處原文是「受遺贈人」。\n原句：前項受有損害之人，對於不當受領之債權人或受遺贈人，得請求返還其不當受領之數額。", "此處不是「被繼承人」。民法第1161條在本題位置規定的是「受遺贈人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「遺囑執行人」。民法第1161條在本題位置規定的是「受遺贈人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「繼承人」。民法第1161條在本題位置規定的是「受遺贈人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是權利主體，再核對條件與例外。", "sources": [{"title": "民法第1161條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1161", "text": "繼承人違反第一千一百五十八條至第一千一百六十條之規定，致被繼承人之債權人受有損害者，應負賠償之責。\n前項受有損害之人，對於不當受領之債權人或受遺贈人，得請求返還其不當受領之數額。\n繼承人對於不當受領之債權人或受遺贈人，不得請求返還其不當受領之數額。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1150-1", "subject": "繼承法", "topic": "犯罪與責任・§1150", "kind": "法條", "question": "【法條原文辨識】依《民法》第1150條，下列節錄的【空格】應填入何者？\n\n「關於遺產管理、分割及執行遺囑之費用，由遺產中支付之。但因繼承人之【空格】而支付者，不在此限。」", "options": ["過失", "緊急避難", "正當防衛", "故意"], "answer": 0, "explanations": ["正確。民法第1150條此處原文是「過失」。\n原句：關於遺產管理、分割及執行遺囑之費用，由遺產中支付之。但因繼承人之過失而支付者，不在此限。", "此處不是「緊急避難」。民法第1150條在本題位置規定的是「過失」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「正當防衛」。民法第1150條在本題位置規定的是「過失」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「故意」。民法第1150條在本題位置規定的是「過失」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是犯罪與責任，再核對條件與例外。", "sources": [{"title": "民法第1150條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1150", "text": "關於遺產管理、分割及執行遺囑之費用，由遺產中支付之。但因繼承人之過失而支付者，不在此限。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1178-1", "subject": "繼承法", "topic": "期間・數額・比例・§1178", "kind": "法條", "question": "【法條原文辨識】依《民法》第1178條，下列節錄的【空格】應填入何者？\n\n「親屬會議依前條規定為報明後，法院應依公示催告程序，定【空格】以上之期限，公告繼承人，命其於期限內承認繼承。」", "options": ["六個月", "一個月", "三個月", "二個月"], "answer": 0, "explanations": ["正確。民法第1178條此處原文是「六個月」。\n原句：親屬會議依前條規定為報明後，法院應依公示催告程序，定六個月以上之期限，公告繼承人，命其於期限內承認繼承。", "此處不是「一個月」。民法第1178條在本題位置規定的是「六個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「三個月」。民法第1178條在本題位置規定的是「六個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「二個月」。民法第1178條在本題位置規定的是「六個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第1178條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1178", "text": "親屬會議依前條規定為報明後，法院應依公示催告程序，定六個月以上之期限，公告繼承人，命其於期限內承認繼承。\n無親屬會議或親屬會議未於前條所定期限內選定遺產管理人者，利害關係人或檢察官，得聲請法院選任遺產管理人，並由法院依前項規定為公示催告。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1178-1-1", "subject": "繼承法", "topic": "親屬與繼承・§1178-1", "kind": "法條", "question": "【法條原文辨識】依《民法》第1178-1條，下列節錄的【空格】應填入何者？\n\n「繼承開始時繼承人之有無不明者，在遺產管理人選定前，法院得因利害關係人或【空格】之聲請，為保存遺產之必要處置。」", "options": ["戶政機關", "法院", "親屬會議", "檢察官"], "answer": 3, "explanations": ["此處不是「戶政機關」。民法第1178-1條在本題位置規定的是「檢察官」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「法院」。民法第1178-1條在本題位置規定的是「檢察官」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「親屬會議」。民法第1178-1條在本題位置規定的是「檢察官」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1178-1條此處原文是「檢察官」。\n原句：繼承開始時繼承人之有無不明者，在遺產管理人選定前，法院得因利害關係人或檢察官之聲請，為保存遺產之必要處置。"], "hint": "先判斷空格要填的是親屬與繼承，再核對條件與例外。", "sources": [{"title": "民法第1178-1條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1178-1", "text": "繼承開始時繼承人之有無不明者，在遺產管理人選定前，法院得因利害關係人或檢察官之聲請，為保存遺產之必要處置。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1185-1", "subject": "繼承法", "topic": "法律要件・§1185", "kind": "法條", "question": "【法條原文辨識】依《民法》第1185條，下列節錄的【空格】應填入何者？\n\n「第一千一百七十八條所定之期限屆滿，無繼承人承認繼承時，其遺產於清償債權並【空格】遺贈物後，如有賸餘，歸屬國庫。」", "options": ["公證", "公告", "交付", "登記"], "answer": 2, "explanations": ["此處不是「公證」。民法第1185條在本題位置規定的是「交付」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「公告」。民法第1185條在本題位置規定的是「交付」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1185條此處原文是「交付」。\n原句：第一千一百七十八條所定之期限屆滿，無繼承人承認繼承時，其遺產於清償債權並交付遺贈物後，如有賸餘，歸屬國庫。", "此處不是「登記」。民法第1185條在本題位置規定的是「交付」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是法律要件，再核對條件與例外。", "sources": [{"title": "民法第1185條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1185", "text": "第一千一百七十八條所定之期限屆滿，無繼承人承認繼承時，其遺產於清償債權並交付遺贈物後，如有賸餘，歸屬國庫。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1204-1", "subject": "繼承法", "topic": "物權種類・§1204", "kind": "法條", "question": "【法條原文辨識】依《民法》第1204條，下列節錄的【空格】應填入何者？\n\n「以遺產之【空格】、收益為遺贈，而遺囑未定返還期限，並不能依遺贈之性質定其期限者，以受遺贈人之終身為其期限。」", "options": ["共有", "占有", "使用", "所有"], "answer": 2, "explanations": ["此處不是「共有」。民法第1204條在本題位置規定的是「使用」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「占有」。民法第1204條在本題位置規定的是「使用」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1204條此處原文是「使用」。\n原句：以遺產之使用、收益為遺贈，而遺囑未定返還期限，並不能依遺贈之性質定其期限者，以受遺贈人之終身為其期限。", "此處不是「所有」。民法第1204條在本題位置規定的是「使用」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是物權種類，再核對條件與例外。", "sources": [{"title": "民法第1204條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1204", "text": "以遺產之使用、收益為遺贈，而遺囑未定返還期限，並不能依遺贈之性質定其期限者，以受遺贈人之終身為其期限。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1156-1-1", "subject": "繼承法", "topic": "期間・數額・比例・§1156-1", "kind": "法條", "question": "【法條原文辨識】依《民法》第1156-1條，下列節錄的【空格】應填入何者？\n\n「債權人得向法院聲請命繼承人於【空格】內提出遺產清冊。」", "options": ["六個月", "三個月", "二個月", "一個月"], "answer": 1, "explanations": ["此處不是「六個月」。民法第1156-1條在本題位置規定的是「三個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1156-1條此處原文是「三個月」。\n原句：債權人得向法院聲請命繼承人於三個月內提出遺產清冊。", "此處不是「二個月」。民法第1156-1條在本題位置規定的是「三個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「一個月」。民法第1156-1條在本題位置規定的是「三個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第1156-1條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1156-1", "text": "債權人得向法院聲請命繼承人於三個月內提出遺產清冊。\n法院於知悉債權人以訴訟程序或非訟程序向繼承人請求清償繼承債務時，得依職權命繼承人於三個月內提出遺產清冊。\n前條第二項及第三項規定，於第一項及第二項情形，準用之。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1211-1", "subject": "繼承法", "topic": "行政程序・§1211", "kind": "法條", "question": "【法條原文辨識】依《民法》第1211條，下列節錄的【空格】應填入何者？\n\n「遺囑未指定遺囑執行人，並未【空格】他人指定者，得由親屬會議選定之；不能由親屬會議選定時，得由利害關係人聲請法院指定之。」", "options": ["委任", "委託", "委辦", "代理"], "answer": 1, "explanations": ["此處不是「委任」。民法第1211條在本題位置規定的是「委託」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1211條此處原文是「委託」。\n原句：遺囑未指定遺囑執行人，並未委託他人指定者，得由親屬會議選定之；不能由親屬會議選定時，得由利害關係人聲請法院指定之。", "此處不是「委辦」。民法第1211條在本題位置規定的是「委託」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「代理」。民法第1211條在本題位置規定的是「委託」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是行政程序，再核對條件與例外。", "sources": [{"title": "民法第1211條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1211", "text": "遺囑未指定遺囑執行人，並未委託他人指定者，得由親屬會議選定之；不能由親屬會議選定時，得由利害關係人聲請法院指定之。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1181-1", "subject": "繼承法", "topic": "權利主體・§1181", "kind": "法條", "question": "【法條原文辨識】依《民法》第1181條，下列節錄的【空格】應填入何者？\n\n「遺產管理人非於第一千一百七十九條第一項第三款所定期間屆滿後，不得對【空格】之任何債權人或受遺贈人，償還債務或交付遺贈物。」", "options": ["受遺贈人", "被繼承人", "繼承人", "遺囑執行人"], "answer": 1, "explanations": ["此處不是「受遺贈人」。民法第1181條在本題位置規定的是「被繼承人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1181條此處原文是「被繼承人」。\n原句：遺產管理人非於第一千一百七十九條第一項第三款所定期間屆滿後，不得對被繼承人之任何債權人或受遺贈人，償還債務或交付遺贈物。", "此處不是「繼承人」。民法第1181條在本題位置規定的是「被繼承人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「遺囑執行人」。民法第1181條在本題位置規定的是「被繼承人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是權利主體，再核對條件與例外。", "sources": [{"title": "民法第1181條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1181", "text": "遺產管理人非於第一千一百七十九條第一項第三款所定期間屆滿後，不得對被繼承人之任何債權人或受遺贈人，償還債務或交付遺贈物。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1188-1", "subject": "繼承法", "topic": "親屬與繼承・§1188", "kind": "法條", "question": "【法條原文辨識】依《民法》第1188條，下列節錄的【空格】應填入何者？\n\n「第一千一百四十五條喪失繼承權之規定，於受【空格】人準用之。」", "options": ["遺贈", "應繼分", "扶養費", "特留分"], "answer": 0, "explanations": ["正確。民法第1188條此處原文是「遺贈」。\n原句：第一千一百四十五條喪失繼承權之規定，於受遺贈人準用之。", "此處不是「應繼分」。民法第1188條在本題位置規定的是「遺贈」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「扶養費」。民法第1188條在本題位置規定的是「遺贈」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「特留分」。民法第1188條在本題位置規定的是「遺贈」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是親屬與繼承，再核對條件與例外。", "sources": [{"title": "民法第1188條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1188", "text": "第一千一百四十五條喪失繼承權之規定，於受遺贈人準用之。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1162-1", "subject": "繼承法", "topic": "權利主體・§1162", "kind": "法條", "question": "【法條原文辨識】依《民法》第1162條，下列節錄的【空格】應填入何者？\n\n「【空格】之債權人，不於第一千一百五十七條所定之一定期限內報明其債權，而又為繼承人所不知者，僅得就賸餘遺產，行使其權利。」", "options": ["受遺贈人", "遺囑執行人", "被繼承人", "繼承人"], "answer": 2, "explanations": ["此處不是「受遺贈人」。民法第1162條在本題位置規定的是「被繼承人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「遺囑執行人」。民法第1162條在本題位置規定的是「被繼承人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1162條此處原文是「被繼承人」。\n原句：被繼承人之債權人，不於第一千一百五十七條所定之一定期限內報明其債權，而又為繼承人所不知者，僅得就賸餘遺產，行使其權利。", "此處不是「繼承人」。民法第1162條在本題位置規定的是「被繼承人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是權利主體，再核對條件與例外。", "sources": [{"title": "民法第1162條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1162", "text": "被繼承人之債權人，不於第一千一百五十七條所定之一定期限內報明其債權，而又為繼承人所不知者，僅得就賸餘遺產，行使其權利。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1153-1", "subject": "繼承法", "topic": "權利主體・§1153", "kind": "法條", "question": "【法條原文辨識】依《民法》第1153條，下列節錄的【空格】應填入何者？\n\n「繼承人對於【空格】之債務，以因繼承所得遺產為限，負連帶責任。」", "options": ["被繼承人", "受遺贈人", "遺囑執行人", "繼承人"], "answer": 0, "explanations": ["正確。民法第1153條此處原文是「被繼承人」。\n原句：繼承人對於被繼承人之債務，以因繼承所得遺產為限，負連帶責任。", "此處不是「受遺贈人」。民法第1153條在本題位置規定的是「被繼承人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「遺囑執行人」。民法第1153條在本題位置規定的是「被繼承人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「繼承人」。民法第1153條在本題位置規定的是「被繼承人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是權利主體，再核對條件與例外。", "sources": [{"title": "民法第1153條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1153", "text": "繼承人對於被繼承人之債務，以因繼承所得遺產為限，負連帶責任。\n繼承人相互間對於被繼承人之債務，除法律另有規定或另有約定外，按其應繼分比例負擔之。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1186-2", "subject": "繼承法", "topic": "期間・數額・比例・§1186", "kind": "法條", "question": "【法條原文辨識】依《民法》第1186條，下列節錄的【空格】應填入何者？\n\n「限制行為能力人，無須經法定代理人之允許，得為遺囑。但未滿【空格】者，不得為遺囑。」", "options": ["十七歲", "十四歲", "七歲", "十六歲"], "answer": 3, "explanations": ["此處不是「十七歲」。民法第1186條在本題位置規定的是「十六歲」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「十四歲」。民法第1186條在本題位置規定的是「十六歲」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「七歲」。民法第1186條在本題位置規定的是「十六歲」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1186條此處原文是「十六歲」。\n原句：限制行為能力人，無須經法定代理人之允許，得為遺囑。但未滿十六歲者，不得為遺囑。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第1186條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1186", "text": "無行為能力人，不得為遺囑。\n限制行為能力人，無須經法定代理人之允許，得為遺囑。但未滿十六歲者，不得為遺囑。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1157-2", "subject": "繼承法", "topic": "期間・數額・比例・§1157", "kind": "法條", "question": "【法條原文辨識】依《民法》第1157條，下列節錄的【空格】應填入何者？\n\n「前項一定期限，不得在【空格】以下。」", "options": ["一個月", "二個月", "三個月", "六個月"], "answer": 2, "explanations": ["此處不是「一個月」。民法第1157條在本題位置規定的是「三個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「二個月」。民法第1157條在本題位置規定的是「三個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1157條此處原文是「三個月」。\n原句：前項一定期限，不得在三個月以下。", "此處不是「六個月」。民法第1157條在本題位置規定的是「三個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第1157條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1157", "text": "繼承人依前二條規定陳報法院時，法院應依公示催告程序公告，命被繼承人之債權人於一定期限內報明其債權。\n前項一定期限，不得在三個月以下。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1218-1", "subject": "繼承法", "topic": "權利主體・§1218", "kind": "法條", "question": "【法條原文辨識】依《民法》第1218條，下列節錄的【空格】應填入何者？\n\n「【空格】怠於執行職務，或有其他重大事由時，利害關係人，得請求親屬會議改選他人；其由法院指定者，得聲請法院另行指定。」", "options": ["遺囑執行人", "受遺贈人", "繼承人", "被繼承人"], "answer": 0, "explanations": ["正確。民法第1218條此處原文是「遺囑執行人」。\n原句：遺囑執行人怠於執行職務，或有其他重大事由時，利害關係人，得請求親屬會議改選他人；其由法院指定者，得聲請法院另行指定。", "此處不是「受遺贈人」。民法第1218條在本題位置規定的是「遺囑執行人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「繼承人」。民法第1218條在本題位置規定的是「遺囑執行人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「被繼承人」。民法第1218條在本題位置規定的是「遺囑執行人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是權利主體，再核對條件與例外。", "sources": [{"title": "民法第1218條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1218", "text": "遺囑執行人怠於執行職務，或有其他重大事由時，利害關係人，得請求親屬會議改選他人；其由法院指定者，得聲請法院另行指定。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1174-2", "subject": "繼承法", "topic": "期間・數額・比例・§1174", "kind": "法條", "question": "【法條原文辨識】依《民法》第1174條，下列節錄的【空格】應填入何者？\n\n「前項拋棄，應於知悉其得繼承之時起【空格】內，以書面向法院為之。」", "options": ["六個月", "三個月", "一個月", "二個月"], "answer": 1, "explanations": ["此處不是「六個月」。民法第1174條在本題位置規定的是「三個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1174條此處原文是「三個月」。\n原句：前項拋棄，應於知悉其得繼承之時起三個月內，以書面向法院為之。", "此處不是「一個月」。民法第1174條在本題位置規定的是「三個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「二個月」。民法第1174條在本題位置規定的是「三個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第1174條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1174", "text": "繼承人得拋棄其繼承權。\n前項拋棄，應於知悉其得繼承之時起三個月內，以書面向法院為之。\n拋棄繼承後，應以書面通知因其拋棄而應為繼承之人。但不能通知者，不在此限。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1154-1", "subject": "繼承法", "topic": "憲政原則・§1154", "kind": "法條", "question": "【法條原文辨識】依《民法》第1154條，下列節錄的【空格】應填入何者？\n\n「繼承人對於被繼承人之權利、【空格】，不因繼承而消滅。」", "options": ["資格", "義務", "責任", "自由"], "answer": 1, "explanations": ["此處不是「資格」。民法第1154條在本題位置規定的是「義務」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1154條此處原文是「義務」。\n原句：繼承人對於被繼承人之權利、義務，不因繼承而消滅。", "此處不是「責任」。民法第1154條在本題位置規定的是「義務」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「自由」。民法第1154條在本題位置規定的是「義務」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是憲政原則，再核對條件與例外。", "sources": [{"title": "民法第1154條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1154", "text": "繼承人對於被繼承人之權利、義務，不因繼承而消滅。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1138-1", "subject": "繼承法", "topic": "權利主體・§1138", "kind": "法條", "question": "【法條原文辨識】依《民法》第1138條，下列節錄的【空格】應填入何者？\n\n「遺產【空格】，除配偶外，依左列順序定之：」", "options": ["遺囑執行人", "受遺贈人", "被繼承人", "繼承人"], "answer": 3, "explanations": ["此處不是「遺囑執行人」。民法第1138條在本題位置規定的是「繼承人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「受遺贈人」。民法第1138條在本題位置規定的是「繼承人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「被繼承人」。民法第1138條在本題位置規定的是「繼承人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1138條此處原文是「繼承人」。\n原句：遺產繼承人，除配偶外，依左列順序定之："], "hint": "先判斷空格要填的是權利主體，再核對條件與例外。", "sources": [{"title": "民法第1138條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1138", "text": "遺產繼承人，除配偶外，依左列順序定之：\n一、直系血親卑親屬。\n二、父母。\n三、兄弟姊妹。\n四、祖父母。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1182-1", "subject": "繼承法", "topic": "權利主體・§1182", "kind": "法條", "question": "【法條原文辨識】依《民法》第1182條，下列節錄的【空格】應填入何者？\n\n「被繼承人之【空格】或受遺贈人，不於第一千一百七十九條第一項第三款所定期間內為報明或聲明者，僅得就賸餘遺產，行使其權利。」", "options": ["債務人", "受益人", "債權人", "第三人"], "answer": 2, "explanations": ["此處不是「債務人」。民法第1182條在本題位置規定的是「債權人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「受益人」。民法第1182條在本題位置規定的是「債權人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1182條此處原文是「債權人」。\n原句：被繼承人之債權人或受遺贈人，不於第一千一百七十九條第一項第三款所定期間內為報明或聲明者，僅得就賸餘遺產，行使其權利。", "此處不是「第三人」。民法第1182條在本題位置規定的是「債權人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是權利主體，再核對條件與例外。", "sources": [{"title": "民法第1182條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1182", "text": "被繼承人之債權人或受遺贈人，不於第一千一百七十九條第一項第三款所定期間內為報明或聲明者，僅得就賸餘遺產，行使其權利。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1189-1", "subject": "繼承法", "topic": "規範強度・§1189", "kind": "法條", "question": "【法條原文辨識】依《民法》第1189條，下列節錄的【空格】應填入何者？\n\n「遺囑【空格】依左列方式之一為之：」", "options": ["應", "得", "無須", "不得"], "answer": 0, "explanations": ["正確。民法第1189條此處原文是「應」。\n原句：遺囑應依左列方式之一為之：", "此處不是「得」。民法第1189條在本題位置規定的是「應」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「無須」。民法第1189條在本題位置規定的是「應」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「不得」。民法第1189條在本題位置規定的是「應」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是規範強度，再核對條件與例外。", "sources": [{"title": "民法第1189條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1189", "text": "遺囑應依左列方式之一為之：\n一、自書遺囑。\n二、公證遺囑。\n三、密封遺囑。\n四、代筆遺囑。\n五、口授遺囑。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1212-1", "subject": "繼承法", "topic": "權利主體・§1212", "kind": "法條", "question": "【法條原文辨識】依《民法》第1212條，下列節錄的【空格】應填入何者？\n\n「遺囑保管人知有繼承開始之事實時，應即將遺囑交付遺囑執行人，並以適當方法通知已知之繼承人；無遺囑執行人者，應通知已知之繼承人、【空格】、受遺贈人及其他利害關係人。無保管人而由繼承人發現遺囑者，亦同。」", "options": ["債權人", "債務人", "受益人", "第三人"], "answer": 0, "explanations": ["正確。民法第1212條此處原文是「債權人」。\n原句：遺囑保管人知有繼承開始之事實時，應即將遺囑交付遺囑執行人，並以適當方法通知已知之繼承人；無遺囑執行人者，應通知已知之繼承人、債權人、受遺贈人及其他利害關係人。無保管人而由繼承人發現遺囑者，亦同。", "此處不是「債務人」。民法第1212條在本題位置規定的是「債權人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「受益人」。民法第1212條在本題位置規定的是「債權人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「第三人」。民法第1212條在本題位置規定的是「債權人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是權利主體，再核對條件與例外。", "sources": [{"title": "民法第1212條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1212", "text": "遺囑保管人知有繼承開始之事實時，應即將遺囑交付遺囑執行人，並以適當方法通知已知之繼承人；無遺囑執行人者，應通知已知之繼承人、債權人、受遺贈人及其他利害關係人。無保管人而由繼承人發現遺囑者，亦同。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1156-3", "subject": "繼承法", "topic": "期間・數額・比例・§1156", "kind": "法條", "question": "【法條原文辨識】依《民法》第1156條，下列節錄的【空格】應填入何者？\n\n「繼承人有數人時，其中【空格】已依第一項開具遺產清冊陳報法院者，其他繼承人視為已陳報。」", "options": ["二人", "一人", "三人", "五人"], "answer": 1, "explanations": ["此處不是「二人」。民法第1156條在本題位置規定的是「一人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1156條此處原文是「一人」。\n原句：繼承人有數人時，其中一人已依第一項開具遺產清冊陳報法院者，其他繼承人視為已陳報。", "此處不是「三人」。民法第1156條在本題位置規定的是「一人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「五人」。民法第1156條在本題位置規定的是「一人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第1156條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1156", "text": "繼承人於知悉其得繼承之時起三個月內開具遺產清冊陳報法院。\n前項三個月期間，法院因繼承人之聲請，認為必要時，得延展之。\n繼承人有數人時，其中一人已依第一項開具遺產清冊陳報法院者，其他繼承人視為已陳報。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1197-1", "subject": "繼承法", "topic": "期間・數額・比例・§1197", "kind": "法條", "question": "【法條原文辨識】依《民法》第1197條，下列節錄的【空格】應填入何者？\n\n「口授遺囑，應由見證人中之一人或利害關係人，於為遺囑人死亡後【空格】內，提經親屬會議認定其真偽，對於親屬會議之認定如有異議，得聲請法院判定之。」", "options": ["六個月", "一個月", "三個月", "二個月"], "answer": 2, "explanations": ["此處不是「六個月」。民法第1197條在本題位置規定的是「三個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「一個月」。民法第1197條在本題位置規定的是「三個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1197條此處原文是「三個月」。\n原句：口授遺囑，應由見證人中之一人或利害關係人，於為遺囑人死亡後三個月內，提經親屬會議認定其真偽，對於親屬會議之認定如有異議，得聲請法院判定之。", "此處不是「二個月」。民法第1197條在本題位置規定的是「三個月」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第1197條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1197", "text": "口授遺囑，應由見證人中之一人或利害關係人，於為遺囑人死亡後三個月內，提經親屬會議認定其真偽，對於親屬會議之認定如有異議，得聲請法院判定之。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1217-1", "subject": "繼承法", "topic": "法律要件・§1217", "kind": "法條", "question": "【法條原文辨識】依《民法》第1217條，下列節錄的【空格】應填入何者？\n\n「遺囑執行人有數人時，其執行職務，以過半數決之。但遺囑另有【空格】者，從其意思。」", "options": ["法律行為", "事實行為", "自然事實", "意思表示"], "answer": 3, "explanations": ["此處不是「法律行為」。民法第1217條在本題位置規定的是「意思表示」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「事實行為」。民法第1217條在本題位置規定的是「意思表示」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「自然事實」。民法第1217條在本題位置規定的是「意思表示」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1217條此處原文是「意思表示」。\n原句：遺囑執行人有數人時，其執行職務，以過半數決之。但遺囑另有意思表示者，從其意思。"], "hint": "先判斷空格要填的是法律要件，再核對條件與例外。", "sources": [{"title": "民法第1217條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1217", "text": "遺囑執行人有數人時，其執行職務，以過半數決之。但遺囑另有意思表示者，從其意思。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1171-2", "subject": "繼承法", "topic": "期間・數額・比例・§1171", "kind": "法條", "question": "【法條原文辨識】依《民法》第1171條，下列節錄的【空格】應填入何者？\n\n「繼承人之連帶責任，自遺產分割時起，如債權清償期在遺產分割後者，自清償期屆滿時起，經過【空格】而免除。」", "options": ["五年", "三年", "一年", "二年"], "answer": 0, "explanations": ["正確。民法第1171條此處原文是「五年」。\n原句：繼承人之連帶責任，自遺產分割時起，如債權清償期在遺產分割後者，自清償期屆滿時起，經過五年而免除。", "此處不是「三年」。民法第1171條在本題位置規定的是「五年」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「一年」。民法第1171條在本題位置規定的是「五年」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「二年」。民法第1171條在本題位置規定的是「五年」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第1171條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1171", "text": "遺產分割後，其未清償之被繼承人之債務，移歸一定之人承受，或劃歸各繼承人分擔，如經債權人同意者，各繼承人免除連帶責任。\n繼承人之連帶責任，自遺產分割時起，如債權清償期在遺產分割後者，自清償期屆滿時起，經過五年而免除。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1211-1-1", "subject": "繼承法", "topic": "親屬與繼承・§1211-1", "kind": "法條", "question": "【法條原文辨識】依《民法》第1211-1條，下列節錄的【空格】應填入何者？\n\n「除遺囑人另有指定外，遺囑執行人就其職務之執行，得請求相當之報酬，其數額由繼承人與遺囑執行人協議定之；不能協議時，由【空格】酌定之。」", "options": ["檢察官", "親屬會議", "戶政機關", "法院"], "answer": 3, "explanations": ["此處不是「檢察官」。民法第1211-1條在本題位置規定的是「法院」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「親屬會議」。民法第1211-1條在本題位置規定的是「法院」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「戶政機關」。民法第1211-1條在本題位置規定的是「法院」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1211-1條此處原文是「法院」。\n原句：除遺囑人另有指定外，遺囑執行人就其職務之執行，得請求相當之報酬，其數額由繼承人與遺囑執行人協議定之；不能協議時，由法院酌定之。"], "hint": "先判斷空格要填的是親屬與繼承，再核對條件與例外。", "sources": [{"title": "民法第1211-1條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1211-1", "text": "除遺囑人另有指定外，遺囑執行人就其職務之執行，得請求相當之報酬，其數額由繼承人與遺囑執行人協議定之；不能協議時，由法院酌定之。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1202-1", "subject": "繼承法", "topic": "法律要件・§1202", "kind": "法條", "question": "【法條原文辨識】依《民法》第1202條，下列節錄的【空格】應填入何者？\n\n「遺囑人以一定之財產為遺贈，而其財產在繼承開始時，有一部分不屬於遺產者，其一部分遺贈為無效；全部不屬於遺產者，其全部遺贈為無效。但遺囑另有【空格】者，從其意思。」", "options": ["意思表示", "法律行為", "事實行為", "自然事實"], "answer": 0, "explanations": ["正確。民法第1202條此處原文是「意思表示」。\n原句：遺囑人以一定之財產為遺贈，而其財產在繼承開始時，有一部分不屬於遺產者，其一部分遺贈為無效；全部不屬於遺產者，其全部遺贈為無效。但遺囑另有意思表示者，從其意思。", "此處不是「法律行為」。民法第1202條在本題位置規定的是「意思表示」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「事實行為」。民法第1202條在本題位置規定的是「意思表示」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「自然事實」。民法第1202條在本題位置規定的是「意思表示」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是法律要件，再核對條件與例外。", "sources": [{"title": "民法第1202條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1202", "text": "遺囑人以一定之財產為遺贈，而其財產在繼承開始時，有一部分不屬於遺產者，其一部分遺贈為無效；全部不屬於遺產者，其全部遺贈為無效。但遺囑另有意思表示者，從其意思。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1144-4", "subject": "繼承法", "topic": "期間・數額・比例・§1144", "kind": "法條", "question": "【法條原文辨識】依《民法》第1144條，下列節錄的【空格】應填入何者？\n\n「三、與第一千一百三十八條所定第四順序之繼承人同為繼承時，其應繼分為遺產【空格】。」", "options": ["二分之一", "三分之二", "四分之一", "三分之一"], "answer": 1, "explanations": ["此處不是「二分之一」。民法第1144條在本題位置規定的是「三分之二」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1144條此處原文是「三分之二」。\n原句：三、與第一千一百三十八條所定第四順序之繼承人同為繼承時，其應繼分為遺產三分之二。", "此處不是「四分之一」。民法第1144條在本題位置規定的是「三分之二」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「三分之一」。民法第1144條在本題位置規定的是「三分之二」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第1144條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1144", "text": "配偶有相互繼承遺產之權，其應繼分，依左列各款定之：\n一、與第一千一百三十八條所定第一順序之繼承人同為繼承時，其應繼分與他繼承人平均。\n二、與第一千一百三十八條所定第二順序或第三順序之繼承人同為繼承時，其應繼分為遺產二分之一。\n三、與第一千一百三十八條所定第四順序之繼承人同為繼承時，其應繼分為遺產三分之二。\n四、無第一千一百三十八條所定第一順序至第四順序之繼承人時，其應繼分為遺產全部。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1219-1", "subject": "繼承法", "topic": "債的效力・§1219", "kind": "法條", "question": "【法條原文辨識】依《民法》第1219條，下列節錄的【空格】應填入何者？\n\n「遺囑人得隨時依遺囑之方式，【空格】遺囑之全部或一部。」", "options": ["承認", "撤回", "通知", "拒絕"], "answer": 1, "explanations": ["此處不是「承認」。民法第1219條在本題位置規定的是「撤回」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1219條此處原文是「撤回」。\n原句：遺囑人得隨時依遺囑之方式，撤回遺囑之全部或一部。", "此處不是「通知」。民法第1219條在本題位置規定的是「撤回」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「拒絕」。民法第1219條在本題位置規定的是「撤回」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是債的效力，再核對條件與例外。", "sources": [{"title": "民法第1219條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1219", "text": "遺囑人得隨時依遺囑之方式，撤回遺囑之全部或一部。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1169-2", "subject": "繼承法", "topic": "物權種類・§1169", "kind": "法條", "question": "【法條原文辨識】依《民法》第1169條，下列節錄的【空格】應填入何者？\n\n「前項【空格】，附有停止條件或未屆清償期者，各繼承人就應清償時債務人之支付能力，負擔保之責。」", "options": ["動產", "不動產", "有價證券", "債權"], "answer": 3, "explanations": ["此處不是「動產」。民法第1169條在本題位置規定的是「債權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「不動產」。民法第1169條在本題位置規定的是「債權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「有價證券」。民法第1169條在本題位置規定的是「債權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1169條此處原文是「債權」。\n原句：前項債權，附有停止條件或未屆清償期者，各繼承人就應清償時債務人之支付能力，負擔保之責。"], "hint": "先判斷空格要填的是物權種類，再核對條件與例外。", "sources": [{"title": "民法第1169條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1169", "text": "遺產分割後，各繼承人按其所得部分，對於他繼承人因分割而得之債權，就遺產分割時債務人之支付能力，負擔保之責。\n前項債權，附有停止條件或未屆清償期者，各繼承人就應清償時債務人之支付能力，負擔保之責。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1214-1", "subject": "繼承法", "topic": "權利主體・§1214", "kind": "法條", "question": "【法條原文辨識】依《民法》第1214條，下列節錄的【空格】應填入何者？\n\n「遺囑執行人就職後，於遺囑有關之財產，如有編製清冊之必要時，應即編製遺產清冊，交付【空格】。」", "options": ["被繼承人", "遺囑執行人", "繼承人", "受遺贈人"], "answer": 2, "explanations": ["此處不是「被繼承人」。民法第1214條在本題位置規定的是「繼承人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「遺囑執行人」。民法第1214條在本題位置規定的是「繼承人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1214條此處原文是「繼承人」。\n原句：遺囑執行人就職後，於遺囑有關之財產，如有編製清冊之必要時，應即編製遺產清冊，交付繼承人。", "此處不是「受遺贈人」。民法第1214條在本題位置規定的是「繼承人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是權利主體，再核對條件與例外。", "sources": [{"title": "民法第1214條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1214", "text": "遺囑執行人就職後，於遺囑有關之財產，如有編製清冊之必要時，應即編製遺產清冊，交付繼承人。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1179-4", "subject": "繼承法", "topic": "期間・數額・比例・§1179", "kind": "法條", "question": "【法條原文辨識】依《民法》第1179條，下列節錄的【空格】應填入何者？\n\n「三、聲請法院依公示催告程序，限定【空格】以上之期間，公告被繼承人之債權人及受遺贈人，命其於該期間內報明債權及為願受遺贈與否之聲明，被繼承人之債權人及受遺贈人為管理人所已知者，應分別通知之。」", "options": ["三年", "一年", "五年", "二年"], "answer": 1, "explanations": ["此處不是「三年」。民法第1179條在本題位置規定的是「一年」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1179條此處原文是「一年」。\n原句：三、聲請法院依公示催告程序，限定一年以上之期間，公告被繼承人之債權人及受遺贈人，命其於該期間內報明債權及為願受遺贈與否之聲明，被繼承人之債權人及受遺贈人為管理人所已知者，應分別通知之。", "此處不是「五年」。民法第1179條在本題位置規定的是「一年」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「二年」。民法第1179條在本題位置規定的是「一年」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是期間・數額・比例，再核對條件與例外。", "sources": [{"title": "民法第1179條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1179", "text": "遺產管理人之職務如左：\n一、編製遺產清冊。\n二、為保存遺產必要之處置。\n三、聲請法院依公示催告程序，限定一年以上之期間，公告被繼承人之債權人及受遺贈人，命其於該期間內報明債權及為願受遺贈與否之聲明，被繼承人之債權人及受遺贈人為管理人所已知者，應分別通知之。\n四、清償債權或交付遺贈物。\n五、有繼承人承認繼承或遺產歸屬國庫時，為遺產之移交。\n前項第一款所定之遺產清冊，管理人應於就職後三個月內編製之；第四款所定債權之清償，應先於遺贈物之交付，為清償債權或交付遺贈物之必要，管理人經親屬會議之同意，得變賣遺產。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1209-1", "subject": "繼承法", "topic": "權利主體・§1209", "kind": "法條", "question": "【法條原文辨識】依《民法》第1209條，下列節錄的【空格】應填入何者？\n\n「遺囑人得以遺囑指定【空格】，或委託他人指定之。」", "options": ["受遺贈人", "遺囑執行人", "被繼承人", "繼承人"], "answer": 1, "explanations": ["此處不是「受遺贈人」。民法第1209條在本題位置規定的是「遺囑執行人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1209條此處原文是「遺囑執行人」。\n原句：遺囑人得以遺囑指定遺囑執行人，或委託他人指定之。", "此處不是「被繼承人」。民法第1209條在本題位置規定的是「遺囑執行人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「繼承人」。民法第1209條在本題位置規定的是「遺囑執行人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是權利主體，再核對條件與例外。", "sources": [{"title": "民法第1209條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1209", "text": "遺囑人得以遺囑指定遺囑執行人，或委託他人指定之。\n受前項委託者，應即指定遺囑執行人，並通知繼承人。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1148-2", "subject": "繼承法", "topic": "權利主體・§1148", "kind": "法條", "question": "【法條原文辨識】依《民法》第1148條，下列節錄的【空格】應填入何者？\n\n「繼承人對於【空格】之債務，以因繼承所得遺產為限，負清償責任。」", "options": ["受遺贈人", "遺囑執行人", "繼承人", "被繼承人"], "answer": 3, "explanations": ["此處不是「受遺贈人」。民法第1148條在本題位置規定的是「被繼承人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「遺囑執行人」。民法第1148條在本題位置規定的是「被繼承人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「繼承人」。民法第1148條在本題位置規定的是「被繼承人」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "正確。民法第1148條此處原文是「被繼承人」。\n原句：繼承人對於被繼承人之債務，以因繼承所得遺產為限，負清償責任。"], "hint": "先判斷空格要填的是權利主體，再核對條件與例外。", "sources": [{"title": "民法第1148條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1148", "text": "繼承人自繼承開始時，除本法另有規定外，承受被繼承人財產上之一切權利、義務。但權利、義務專屬於被繼承人本身者，不在此限。\n繼承人對於被繼承人之債務，以因繼承所得遺產為限，負清償責任。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}, {"id": "lawtext-B0000001-1162-2-5", "subject": "繼承法", "topic": "物權種類・§1162-2", "kind": "法條", "question": "【法條原文辨識】依《民法》第1162-2條，下列節錄的【空格】應填入何者？\n\n「繼承人對於不當受領之【空格】人或受遺贈人，不得請求返還其不當受領之數額。」", "options": ["債權", "動產", "有價證券", "不動產"], "answer": 0, "explanations": ["正確。民法第1162-2條此處原文是「債權」。\n原句：繼承人對於不當受領之債權人或受遺贈人，不得請求返還其不當受領之數額。", "此處不是「動產」。民法第1162-2條在本題位置規定的是「債權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「有價證券」。民法第1162-2條在本題位置規定的是「債權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。", "此處不是「不動產」。民法第1162-2條在本題位置規定的是「債權」；請按題示條文的主體、條件與例外判斷，不要將其他制度的用語套入。"], "hint": "先判斷空格要填的是物權種類，再核對條件與例外。", "sources": [{"title": "民法第1162-2條｜全國法規資料庫", "url": "https://law.moj.gov.tw/LawClass/LawSingle.aspx?pcode=B0000001&flno=1162-2", "text": "繼承人違反第一千一百六十二條之一規定者，被繼承人之債權人得就應受清償而未受償之部分，對該繼承人行使權利。\n繼承人對於前項債權人應受清償而未受償部分之清償責任，不以所得遺產為限。但繼承人為無行為能力人或限制行為能力人，不在此限。\n繼承人違反第一千一百六十二條之一規定，致被繼承人之債權人受有損害者，亦應負賠償之責。\n前項受有損害之人，對於不當受領之債權人或受遺贈人，得請求返還其不當受領之數額。\n繼承人對於不當受領之債權人或受遺贈人，不得請求返還其不當受領之數額。"}], "status": "reviewed", "checkedAt": "2026-09-20", "basisDate": "2026-09-20", "eventDate": "", "reviewNote": "官方條文原文填空；已逐題以保留的官方全文還原比對，四個選項僅一項符合原文。本題考條文辨識，非個案法律結論，具體適用仍須考慮特別法與司法解釋。憲法已排除停止適用的本文規定；本批未採尚未施行的民法第1223條新文。", "origin": "本站自編・法條辨識（非國考原題）", "revision": 1, "archiveFile": "reviewed-800.json", "currentReview": "舊版答案，尚未在本次逐題複核"}]);
